algorithms.pseudocode:
INPUT : invertible A in R^{n x n}
OUTPUT: the generator of the intersection body of E(A)

1. G <- A A^T                                   # positive definite Gram matrix
2. (mu, U) <- jacobi_eigendecomposition(G)
3. S <- U diag(sqrt(mu)) U^T                    # the positive definite square root
4. delta <- |det A|
5. RETURN delta * S^{-1}

PROPERTIES (checkable numerically):
  det(delta * S^{-1}) = delta^{n-1}
  if A is positive definite then delta * S^{-1} = (det A) A^{-1}
  if in addition det A = 1 then the map is A -> A^{-1}, an involution whose
  unique fixed point is the identity matrix
